const StyledDataGridBase = styled(DataGrid)({
    width: "100%",
    minWidth: 0,
    "&.MuiDataGrid-autoHeight": {
        overflow: "visible",

        "& .MuiDataGrid-main": {
            overflow: "visible",
        },

        "& .MuiDataGrid-columnHeaders": {
            position: "sticky",
            top: "var(--app-header-height)",
            zIndex: 2,
            backgroundColor: "var(--color-surface-soft)",
            boxShadow: "0 1px 0 var(--color-border)",
        },
    },
});

export const StyledDataGrid = (props: DataGridProps) => {
    const {language} = useTranslation();
    const localeText = useMemo(
        () => ({
            ...getDataGridLocaleText(language),
            ...props.localeText,
        }),
        [language, props.localeText],
    );

    return React.createElement(StyledDataGridBase, {
        ...props,
        localeText,
    });
};
