import {getApiErrorMessage} from "../../api/errors";
import React, {useMemo, useState} from "react";
import {
    Avatar,
    Breadcrumbs,
    Button,
    CardActions,
    CardContent,
    CardHeader,
    CardMedia,
    Dialog,
    DialogActions,
    DialogContent,
    DialogContentText,
    DialogTitle,
    Link,
    Typography,
} from "@mui/material";
import {NavLink, useLocation, useNavigate, useParams} from "react-router-dom";
import AddCircleIcon from "@mui/icons-material/AddCircle";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import RemoveCircleIcon from "@mui/icons-material/RemoveCircle";
import {useAppDispatch} from "../../store/store";
import {IShortProduct} from "../../models/product";
import Loader from "../../ui/loader/loader";
import CoreButton from "../../ui/buttons/coreButton";
import CoreTextField from "../../ui/textFields/coreTextField";
import {CategoryType, ICreateCategory} from "../../models/category";
import {
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
} from "../../ui/commonStyled/commonStyled";
import {
    CategoriesGrid,
    CategoryNameDiv,
    ProductCountBadge,
    ProductQuantityControls,
    ProductsListDiv,
    StyledProductCard,
} from "./styled";
import {
    categoriesApi,
    useCreateCategoryMutation,
    useGetCategoriesHierarchyQuery,
} from "./categoriesApi";
import {
    useGetProductsByCategoryIdQuery,
    useMoveProductsToCategoryMutation,
} from "../products/productsApi";
import {useGetServicesByCategoryIdQuery} from "../services/servicesApi";
import {IOrderItem, OrderItemType} from "../../models/order";
import {useTranslation} from "../../i18n";
import {readCreateOrderDraft, writeOrderItemsToCreateOrderDraft} from "../orders/createOrder/createOrderDraft";
import {toast} from "react-toastify";

interface IProps {
    isOrder?: boolean;
    categoryType?: CategoryType;
    basePath?: string;
}

const CategoriesHierarchy = ({
                                 isOrder,
                                 categoryType = CategoryType.Product,
                                 basePath = "/productCategories",
                             }: IProps) => {
    const dispatch = useAppDispatch();
    const {id} = useParams();
    const {pathname} = useLocation();
    const draftOrderId = pathname.match(/^\/ordersManagement\/editOrder\/([^/]+)\//)?.[1];
    const navigate = useNavigate();
    const {t} = useTranslation();
    const effectiveCategoryType = isOrder ? CategoryType.Product : categoryType;
    const isProductCategory = effectiveCategoryType === CategoryType.Product;
    const [createCategory, {isLoading: isCreatingCategory}] = useCreateCategoryMutation();
    const [moveProductsToCategory, {isLoading: isMovingProducts}] = useMoveProductsToCategoryMutation();

    const [orderItems, setOrderItems] = useState<IOrderItem[]>(() => {
        return readCreateOrderDraft(draftOrderId).orderItems || [];
    });
    const orderCategoryBasePath = useMemo(() => {
        const editOrderMatch = pathname.match(/^\/ordersManagement\/editOrder\/([^/]+)\/categories/);

        if (editOrderMatch) {
            return `/ordersManagement/editOrder/${editOrderMatch[1]}/categories`;
        }

        return "/ordersManagement/createOrder/categories";
    }, [pathname]);

    const {data: categories = [], isLoading: isLoadingCategory} = useGetCategoriesHierarchyQuery({
        parentCategoryId: id,
        type: effectiveCategoryType,
    });
    const {
        data: products = [],
        isLoading: isLoadingProducts,
    } = useGetProductsByCategoryIdQuery(id ? id : "-1", {skip: !id || !isProductCategory});
    const {
        data: services = [],
        isLoading: isLoadingServices,
    } = useGetServicesByCategoryIdQuery(id ? id : "-1", {skip: !id || isProductCategory});

    const [open, setOpen] = useState(false);
    const [newCategory, setNewCategory] = useState<ICreateCategory>({
        name: "",
        type: effectiveCategoryType,
    });

    async function createCategoryHandler() {
        const categoryPayload: ICreateCategory = {
            name: newCategory.name,
            type: effectiveCategoryType,
            parentCategoryId: id,
        };

        try {
            await createCategory(categoryPayload).unwrap();
            toast.success(t("Категория была создана"));
            setNewCategory({name: "", type: effectiveCategoryType});
            setOpen(false);
            navigate(basePath, {replace: true});
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось сохранить категорию.")));
        }
    }

    async function moveProductsAndCreateCategory() {
        const categoryPayload: ICreateCategory = {
            name: newCategory.name,
            type: CategoryType.Product,
        };

        if (!id) return;
        try {
            await moveProductsToCategory({categoryId: id, category: categoryPayload}).unwrap();
            dispatch(categoriesApi.util.invalidateTags(["Categories"]));
            toast.success(t("Категория была создана"));
            setNewCategory({name: "", type: effectiveCategoryType});
            setOpen(false);
            navigate(basePath, {replace: true});
        } catch (failure) {
            toast.error(getApiErrorMessage(failure, t("Не удалось сохранить категорию.")));
        }
    }

    function handleCategoryAdd() {
        setOpen(true);
    }

    if (
        isLoadingCategory ||
        (isProductCategory ? isLoadingProducts : isLoadingServices)
    ) {
        return <Loader/>;
    }

    function handleAddProductOption(product: IShortProduct) {
        const productOption: IOrderItem = {
            id: product.id,
            itemType: OrderItemType.Product,
            productId: product.id,
            serviceId: null,
            name: product.name,
            imageName: product.imageName || null,
            price: product.price,
            count: 1,
            sum: 0,
        };

        const orderItemIndex = orderItems.findIndex((item) => item.id === product.id);

        if (orderItemIndex >= 0) {
            const updatedOrderItems = orderItems.map((item, index) => {
                if (index === orderItemIndex) {
                    return {...item, count: item.count + 1};
                }
                return item;
            });
            setOrderItems(updatedOrderItems);
            writeOrderItemsToCreateOrderDraft(updatedOrderItems, draftOrderId);
        } else {
            const updatedOrderItems = [...orderItems, productOption];
            setOrderItems(updatedOrderItems);
            writeOrderItemsToCreateOrderDraft(updatedOrderItems, draftOrderId);
        }
    }

    function handleRemoveProductOption(productId: number) {
        const orderItemIndex = orderItems.findIndex((item) => item.id === productId);

        if (orderItemIndex >= 0) {
            const updatedOrderItems = orderItems.map((item, index) => {
                if (index === orderItemIndex) {
                    const newCount = item.count - 1;
                    if (newCount <= 0) {
                        return null;
                    }
                    return {...item, count: newCount};
                }
                return item;
            }).filter((item): item is IOrderItem => item !== null);

            setOrderItems(updatedOrderItems);
            writeOrderItemsToCreateOrderDraft(updatedOrderItems, draftOrderId);
        }
    }

    const hasBlockingItems = isProductCategory ? products.length > 0 : services.length > 0;
    const saveCategory = hasBlockingItems && isProductCategory
        ? moveProductsAndCreateCategory
        : createCategoryHandler;

    return (
        <MainDiv>
            <Dialog
                fullWidth
                open={open}
                onClose={() => setOpen(false)}
            >
                {hasBlockingItems && (
                    <>
                        <DialogTitle>{t("Subcategory required")}</DialogTitle>
                        <DialogContent>
                            <DialogContentText>
                                {isProductCategory
                                    ? t("This category already has products. Create a subcategory for the existing catalog items.")
                                    : t("This category already has services. Create a service subcategory to keep the service tree consistent.")}
                            </DialogContentText>
                        </DialogContent>
                    </>
                )}
                <DialogTitle>{t("Create category")}</DialogTitle>
                <DialogContent>
                    <CoreTextField
                        label={t("Category name")}
                        type="text"
                        value={newCategory.name}
                        onChange={(event: any) =>
                            setNewCategory({
                                name: event.target.value,
                                type: effectiveCategoryType,
                            })
                        }
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpen(false)}>{t("Cancel")}</Button>
                    <Button
                        disabled={isCreatingCategory || isMovingProducts}
                        onClick={saveCategory}
                    >
                        {t("Save")}
                    </Button>
                </DialogActions>
            </Dialog>

            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>
                        {isOrder
                            ? t("Product selection")
                            : isProductCategory
                                ? t("Product category hierarchy")
                                : t("Service category hierarchy")}
                    </PageTitle>
                    <PageSubtitle>
                        {isOrder
                            ? t("Browse product categories and add products to the order.")
                            : t("Browse, split, and maintain the selected catalog category tree.")}
                    </PageSubtitle>
                </PageTitleGroup>
                {!isOrder && (
                    <CoreButton
                        muiType="success"
                        text={t("Add category")}
                        onClick={() => handleCategoryAdd()}
                    />
                )}
            </PageHeader>

            <Surface>
                <Breadcrumbs separator={<ChevronRightIcon fontSize="small"/>} aria-label={t("Category navigation")}>
                    <Link
                        component={NavLink}
                        replace={!!isOrder}
                        underline="hover"
                        color="inherit"
                        to={isOrder ? orderCategoryBasePath : basePath}
                    >
                        {isProductCategory ? t("Product categories") : t("Service categories")}
                    </Link>
                    <Typography color="text.primary">{id ? t("Category {id}", {id}) : t("Root")}</Typography>
                </Breadcrumbs>

                {categories.length > 0 && (
                    <CategoriesGrid>
                        {categories.map((category) => (
                            <NavLink
                                replace={!!isOrder}
                                key={category.id}
                                style={{textDecoration: "none"}}
                                to={
                                    isOrder
                                        ? `${orderCategoryBasePath}/${category.id}`
                                        : `${basePath}/hierarchy/${category.id}`
                                }
                            >
                                <CategoryNameDiv>
                                    <h3>{category.name}</h3>
                                    <ChevronRightIcon fontSize="small"/>
                                </CategoryNameDiv>
                            </NavLink>
                        ))}
                    </CategoriesGrid>
                )}
            </Surface>

            {isProductCategory ? (
                <ProductsListDiv>
                    {products.map((product) => {
                        const selectedIndex = orderItems.findIndex((item) => item.id === product.id);
                        const selectedCount = selectedIndex >= 0 ? orderItems[selectedIndex]?.count : 0;

                        return (
                            <StyledProductCard key={product.id}>
                                <CardHeader
                                    avatar={<Avatar>{product.name?.[0] ?? "P"}</Avatar>}
                                    title={product.name}
                                    subheader={`${product.price} BYN`}
                                />
                                <CardMedia
                                    sx={{objectFit: "contain", background: "var(--color-surface-soft)"}}
                                    component="img"
                                    height="180"
                                    image={product.imageName}
                                    alt={product.name}
                                />
                                <CardContent>
                                    <Typography variant="body2" color="text.secondary">
                                        {product.category}
                                    </Typography>
                                </CardContent>
                                {isOrder && (
                                    selectedIndex === -1 ? (
                                        <CardActions sx={{padding: "0 16px 16px"}}>
                                            <CoreButton
                                                onClick={() => handleAddProductOption(product)}
                                                muiType="success"
                                                text={t("Add to order")}
                                            />
                                        </CardActions>
                                    ) : (
                                        <ProductQuantityControls>
                                            <CoreButton
                                                muiType="success"
                                                onClick={() => handleAddProductOption(product)}
                                                rightIcon={<AddCircleIcon/>}
                                                ariaLabel={t("Add more: {name}", {name: product.name})}
                                            />
                                            <ProductCountBadge>{selectedCount}</ProductCountBadge>
                                            <CoreButton
                                                muiType="error"
                                                onClick={() => handleRemoveProductOption(product.id)}
                                                leftIcon={<RemoveCircleIcon/>}
                                                ariaLabel={t("Decrease quantity: {name}", {name: product.name})}
                                            />
                                        </ProductQuantityControls>
                                    )
                                )}
                            </StyledProductCard>
                        );
                    })}
                </ProductsListDiv>
            ) : (
                <ProductsListDiv>
                    {services.map((service) => (
                        <StyledProductCard key={service.id}>
                            <CardHeader
                                avatar={<Avatar>{service.name?.[0] ?? "S"}</Avatar>}
                                title={service.name}
                                subheader={`${service.price} BYN`}
                            />
                            <CardContent>
                                <Typography variant="body2" color="text.secondary">
                                    {service.category || t("Service")}
                                </Typography>
                            </CardContent>
                        </StyledProductCard>
                    ))}
                </ProductsListDiv>
            )}
        </MainDiv>
    );
};

export default CategoriesHierarchy;
